import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

import { findSheets, parseDxf } from "@/lib/dxf";

// Fixture generated by backend app/application/rebar_detailing.py (ezdxf, DXF R2010) for a 1-bay, 1-storey frame.
const text = readFileSync(join(__dirname, "fixtures", "rebar-small.dxf"), "utf8");

describe("rebar detailing DXF in the built-in viewer", () => {
  it("parses ezdxf R2010 output and finds the three sheets", () => {
    const doc = parseDxf(text);
    const layers = new Set(doc.entities.map((e) => e.layer));
    for (const l of ["REBAR_MAIN", "REBAR_STIRRUP", "CONCRETE", "TABLE", "TITLE"]) expect(layers.has(l), l).toBe(true);
    const sheets = findSheets(doc.entities);
    expect(sheets.map((s) => s.name)).toEqual(["R-01 BEAM REINFORCEMENT DETAILS", "R-02 COLUMN REINFORCEMENT DETAILS", "R-03 BAR BENDING SCHEDULE"]);
    expect(doc.entities.some((e) => e.type === "CIRCLE" && e.layer === "REBAR_MAIN")).toBe(true);
    expect(doc.entities.some((e) => e.type === "TEXT" && e.text.includes("TOTAL STEEL"))).toBe(true);
  });
});
